python3 - <<'EOF'
import hashlib, itertools
rows = [
    (1, "sarah.johnson", "sarah.johnson@techcorp.com", "5826ca9ba601ea29138017a4e2a45870edaae980b871d65d9d2f0a27cc840a71"),
    (11, "admin", "admin@techcorp.com", "79a433ab39d5e093d617113e73daea93833398bba84e3996815f94e2c84a43e1"),
]
pwds = ["password", "Password", "passw0rd", "Password1", "password123", "Password123", "Password123!", "admin", "letmein", "welcome", "Welcome123", "user123", "techcorp", "Techcorp123"]
for uid, uname, email, h in rows:
    found = False
    for p in pwds:
        variants = {
            p,
            uname + p, p + uname, uname + ":" + p, p + ":" + uname,
            email.split("@")[0] + p, p + email.split("@")[0],
            email + p, p + email,
            uname + p + "@techcorp.com",
        }
        for v in variants:
            if hashlib.sha256(v.encode()).hexdigest() == h:
                print(f"uid {uid}: sha256({v!r})")
                found = True
                break
        if found: break
    if not found:
        print(f"uid {uid}: no match among probed variants")
EOF
